int productOfDigits(int n) {
    int prod = 0;
    while (n > 0) {
        prod *= n % 10;
        n /= 10;
    }
    return prod;
}

int countDigits(int n) {
    int c = 0;
    while (n > 0) {
        c++;
        n /= 10;
    }
    return c;
}
